class Solution:
    def oddCells(self, m: int, n: int, indices: List[List[int]]) -> int:
        mat = [[0] * n for _ in range(m)]
        for r, c in indices:
            for j in range(n):
                mat[r][j] += 1
            for i in range(m):
                mat[i][c] += 1
        return sum(x % 2 for row in mat for x in row)

