class Solution {
public:
    int oddCells(int m, int n, vector<vector<int>>& indices) {
        vector<vector<int>> mat(m, vector<int>(n, 0));
        for (auto& rc : indices) {
            for (int j = 0; j < n; j++) mat[rc[0]][j]++;
            for (int i = 0; i < m; i++) mat[i][rc[1]]++;
        }
        int ans = 0;
        for (auto& row : mat)
            for (int x : row) ans += x % 2;
        return ans;
    }
};

