class Solution:
    def oddCells(self, m: int, n: int, indices: List[List[int]]) -> int:
        rows = [0] * m
        cols = [0] * n
        for r, c in indices:
            rows[r] += 1
            cols[c] += 1
        R = sum(x % 2 for x in rows)
        C = sum(x % 2 for x in cols)
        return R * (n - C) + (m - R) * C

